// Environment variable types
// If using react-native-config, these would be automatically generated
declare module '@env' {
    export const APP_NAME: string;
    export const APP_ENV: string;
    export const API_URL_DEV: string;
    export const API_URL_STAGING: string;
    export const API_URL_PRODUCTION: string;
    export const API_TIMEOUT: string;
    export const ENABLE_ANALYTICS: string;
    export const ENABLE_CRASH_REPORTING: string;
    export const ENABLE_DEBUG_MENU: string;
    export const DEEP_LINK_SCHEME: string;
    export const DEEP_LINK_HOST: string;
}
